meth_col_names = {}
for col in range(3, 18):
    val = ws_meth.cell(row=2, column=col).value
    if val is not None:
        meth_col_names[col] = val

print("Methodology sources:", meth_col_names)

# Raw data
ws_raw = wb['RawData']
raw_col_names = {}
for col in range(2, 17):
    val = ws_raw.cell(row=4, column=col).value
    if val is not None:
        raw_col_names[col] = val

print("Raw data sources:", raw_col_names)

# Map methodology source -> raw data column
# By matching source names
src_to_raw_col = {}
for mcol, msrc in meth_col_names.items():
    for rcol, rsrc in raw_col_names.items():
        if msrc == rsrc:
            src_to_raw_col[mcol] = rcol
            break

print("Source mapping:", src_to_raw_col)

# Parse segments (rows 4-13, col B)
def to_float(v):
    if v is None:
        return None
    try:
        return float(v)
    except (ValueError, TypeError):
        return None

segments = []
for row in range(4, 14):
    seg_name = ws_meth.cell(row=row, column=2).value
    if seg_name is None or seg_name == 'Total':
        continue
    mappings = []
    for mcol in range(3, 18):
        w = to_float(ws_meth.cell(row=row, column=mcol).value)
        if w is not None:
            if mcol in src_to_raw_col:
                mappings.append((src_to_raw_col[mcol], w))
    segments.append((seg_name, mappings))

print("\nSegments parsed:")
for sn, ms in segments:
    parts = []
    for rc, w in ms:
        parts.append(f"{raw_col_names[rc]}={w}")
    print(f"  {sn}: {parts}")

# Read raw data by year
years_data = {}
for row in range(5, ws_raw.max_row + 1):
    year = ws_raw.cell(row=row, column=1).value
    if year is None:
        continue
    rd = {}
    for col in range(2, 17):
        rd[col] = ws_raw.cell(row=row, column=col).value
    years_data[year] = rd

print("\nYears:", sorted(years_data.keys()))

# Verify a specific value
print("\nVerification - Auto OEM (Electric=col 7) 2015:")
print("  Raw Electric 2015:", to_float(years_data[2015][7]))
print("  Row 6 col H:", ws_raw.cell(row=6, column=8).value)

# Calculate segment values
target_years = list(range(2015, 2025))
seg_vals = {}
for sn, ms in segments:
    seg_vals[sn] = {}
    for year in target_years:
        total = 0.0
        for rcol, w in ms:
            v = to_float(years_data[year].get(rcol))
            if v is None:
                v = 0.0
            total += v * w
        seg_vals[sn][year] = total
        print(f"  {sn} {year}: {total}")

# YoY growth
growth = {}
for sn in [s[0] for s in segments]:
    growth[sn] = {}
    for i, year in enumerate(target_years):
        if i == 0:
            growth[sn][year] = None
        else:
            prev = seg_vals[sn][target_years[i-1]]
            curr = seg_vals[sn][year]
            if prev and prev != 0:
                growth[sn][year] = round((curr - prev) / prev * 100, 1)
            else:
                growth[sn][year] = None
        print(f"  {sn} YoY {year}: {growth[sn][year]}")

# Write output
wb_out = Workbook()
ws_out = wb_out.active
headers = ['Year'] + [s[0] for s in segments]
ws_out.append(headers)
for year in target_years:
    row = [year]
    for sn in [s[0] for s in segments]:
        row.append(growth[sn][year])
    ws_out.append(row)

wb_out.save('/app/segment_growth_rates.xlsx')
print("\nSaved successfully!")

